def compute(vars):
    options = vars["v1"]
    exercise_price = vars["v2"]
    value = options * exercise_price
    return {
        "value": value,
        "trace": {
            "options": options,
            "exercise_price": exercise_price,
            "product_usd": value,
            "display_conversion": None,
            "note": "The source reporting scale is unknown, so conversion to millions is unsupported.",
            "output_meta": {
                "currency": "USD",
                "scale": None,
                "unit": "currency"
            }
        }
    }
